(() => {
  // 24 px on an 800x480 panel, the same share of a bigger one.
  const scale = Math.min((context.imageWidth || 800) / 800, (context.imageHeight || 480) / 480)
  return Math.round(24 * Math.max(0.75, scale))
})()

(() => {
  // The message's outline: 4 px on an 800x480 panel, the same share of any other.
  const scale = Math.min((context.imageWidth || 800) / 800, (context.imageHeight || 480) / 480)
  return Math.max(2, Math.round(4 * scale))
})()

