// No key, no photo: a calm background the message reads on, and a small line
// at the bottom (inside the circle on a round panel) saying what is missing.
export function noKey(app, context, w, h) {
  frameos.log('No Unsplash API key: add one in the settings for a background photo.')
  const paper = app.frame.paper === true
  const round = context.round === true
  const size = Math.max(12, Math.round(Math.min(w, h) / 30))
  const bottom = Math.round(h * (round ? 0.15 : 0.04))
  const side = Math.round(w * (round ? 0.22 : 0.05))
  const colors = paper ? 'bg-white text-black' : 'bg-gradient-to-b from-slate-600 to-slate-900 text-slate-200'
  return (
    <div className={`flex flex-col justify-end items-center w-[${w}px] h-[${h}px] px-[${side}px] pb-[${bottom}px] ${colors}`}>
      <div className={`text-[${size}px] text-center`}>No background photo: add an Unsplash API key in the settings.</div>
    </div>
  )
}

